window.REPORT_PRELOAD_CACHE["WCN.html"] = {"version":"06475735fadbe91791b5d22ddd334f6aadf8d61d190a33dbfe6532a9d7092b64","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>威斯特连接公司 Waste Connections, Inc. (NYSE: WCN) 深度研究报告：北美固废巨头定价权、2026Q3超预期业绩与全美收购网络扩张</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n wcnblue: {\n 300: '#93C5FD',\n 400: '#60A5FA',\n 500: '#2563EB',\n 600: '#1D4ED8',\n 700: '#1E40AF',\n },\n wcnteal: {\n 400: '#22D3EE',\n 500: '#06B6D4',\n 600: '#0891B2',\n },\n emerald: {\n 400: '#34D399',\n 500: '#10B981',\n 600: '#059669',\n },\n }\n }\n }\n }\n </script>\n\n <style>\n ::-webkit-scrollbar {\n width: 6px;\n height: 6px;\n }\n ::-webkit-scrollbar-track {\n background: transparent;\n }\n ::-webkit-scrollbar-thumb {\n background: #94A3B8;\n border-radius: 3px;\n }\n .dark ::-webkit-scrollbar-thumb {\n background: #475569;\n }\n\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n display: none !important;\n }\n main {\n margin-left: 0 !important;\n padding: 0 !important;\n }\n section {\n break-inside: avoid;\n }\n }\n\n .report-card {\n transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n }\n .report-card:hover {\n transform: translateY(-2px);\n }\n\n .nav-link.active {\n background: linear-gradient(90deg, rgba(37, 99, 235, 0.24) 0%, rgba(16, 185, 129, 0.06) 100%);\n border-left: 3px solid #2563EB;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-wcnblue-500 selection:text-white transition-colors duration-200\">\n\n <!-- 顶部全局阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-wcnblue-600 via-wcnblue-400 to-emerald-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶部导航栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-wcnblue-500 to-wcnteal-500 flex items-center justify-center font-extrabold text-white text-xs shadow\">\n WCN\n </div>\n <div>\n <div class=\"text-[11px] text-wcnblue-300 font-semibold tracking-wider uppercase\">NYSE: WCN · Solid Waste Leader</div>\n <div class=\"text-sm font-bold leading-tight\">威斯特连接 深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端折叠抽屉菜单 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">WCN 研报目录导航</span>\n <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n </button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 商业模式与垃圾独占网络架构</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与核心护城河</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 北美固废与环保巨头横向对比</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与现金流复利推演</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>北美环保与公用事业研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (Q3 26 / SEC 10-Q)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-wcnblue-500 via-wcnblue-600 to-wcnteal-500 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-wcnblue-500/25\">\n WCN\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-wcnblue-300 bg-wcnblue-500/15 px-2 py-0.5 rounded\">NYSE: WCN</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">威斯特连接深度研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 北美次级/独占市场固废垃圾处理巨头 · 核心价格 5.5% 强劲支撑、Q3 盈利超预期与全美 M&A 整合\n </p>\n </div>\n\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">参考股价 (52周区间)</span>\n <span class=\"font-mono font-bold text-white\">~$196.14 <span class=\"text-slate-400 text-[10px]\">($146-$197)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">Q3 2026 总营收</span>\n <span class=\"font-mono font-bold text-emerald-400\">$26.4 亿 <span class=\"text-slate-400\">(+7.3% YoY)</span></span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">调整后 EBITDA 利润率</span>\n <span class=\"font-mono font-bold text-wcnblue-300\">34.0% (+20 bps)</span>\n </div>\n </div>\n\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-wcnblue-400 mr-2\">00</span>执行摘要与核心指标</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>商业模式与固废独占网络架构</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与核心护城河</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>北美固废与环保巨头横向对比</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与自由现金流推演</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n <svg class=\"w-3.5 h-3.5 text-wcnblue-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-wcnblue-500 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色护眼模式</span>\n <span class=\"hidden dark:inline\">机构亮色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-r from-wcnblue-500 to-wcnblue-600 hover:from-wcnblue-600 hover:to-wcnblue-700 text-white text-xs font-extrabold transition shadow-sm cursor-pointer\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span>打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. Hero 研报封面区与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-wcnblue-500/15 text-wcnblue-700 dark:text-wcnblue-300 font-bold border border-wcnblue-500/30\">评级：买入 / 北美公用事业与优质固废核心底仓</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026Q3 超预期财报、指引上调与次级市场加密期</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>覆盖时间：2026年11月</span>\n <span>NYSE: WCN</span>\n </div>\n </div>\n\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#3B82F6 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-wcnblue-500/20 border border-wcnblue-400/40 text-wcnblue-300 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-wcnblue-400 animate-pulse\"></span>\n <span>CORE THESIS · Q3 营收 $26.4亿（+7.3% YoY）超预期 × 核心价格 5.5% 强劲支撑 × 全年业绩指引再次上调</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 威斯特连接公司 Waste Connections, Inc. (NYSE: WCN) 深度研究报告：北美固废巨头定价权、2026Q3超预期业绩与全美收购网络扩张\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 北美次级与独占市场固废垃圾处理巨头 <strong class=\"text-white\">Waste Connections（NYSE: WCN）</strong>交出了一份卓越的 <strong class=\"text-white\">2026 财年第三季度财报</strong>：单季总营收达到 <strong class=\"text-wcnblue-300\">$26.38 亿美元（同比增长 7.3%）</strong>，归属于公司的净利润达到 <strong class=\"text-emerald-400\">$3.59 亿美元（稀释 EPS 达 $1.43，同比大增 28.8%）</strong>。\n 得益于美国及加拿大次级市场的坚实定价纪律（<strong class=\"text-white\">核心价格上涨 5.5%</strong>，收益率达 4.3%）与填埋场特殊废弃物回暖，公司调整后 EBITDA 达到 <strong class=\"text-wcnblue-300\">$8.958 亿美元</strong>（利润率扩至 34.0%）。管理层顺势再次上调全年营收及调整后指引，展现出无可匹敌的抗周期防御与成长复利属性。\n </p>\n\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">Q3 营收与盈利双双超越预期</div>\n <div class=\"text-white font-semibold\">Q3 营收达 $2.64B（+7.3% YoY），净利润达 $359M（+25.5%），稀释 EPS 达 $1.43（+28.8%）</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">强劲的定价纪律与利润率扩张</div>\n <div class=\"text-wcnblue-300 font-semibold\">核心价格大增 5.5%，调整后 EBITDA 利润率达 34.0%（底层利润率扩张 50 个基点）</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">再次上调全年业绩展望</div>\n <div class=\"text-emerald-400 font-semibold\">全年营收预期上调至 $10.09B，预计净经营现金流达 $2.64B–$2.69B，调整后 FCF 达 $1.4B+</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4个核心 KPI 卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>总市值与最新股价</span>\n <span class=\"p-1.5 rounded-lg bg-wcnblue-500/15 text-wcnblue-600 dark:text-wcnblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~$49.0B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">~$196.14</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 北美固废处理核心巨头，总市值达 ~490 亿美元，股价逼近 52 周高点 ($196.76)。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q3 2026 净销售额</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$2.64B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">+7.3% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 单季净营收达 $26.38 亿美元，超越市场共识，内部固废业务增长达 4.5%。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q3 调整后 EBITDA & 利润率</span>\n <span class=\"p-1.5 rounded-lg bg-wcnteal-500/15 text-wcnteal-600 dark:text-wcnteal-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$895.8M</span>\n <span class=\"text-xs font-bold text-wcnteal-600 dark:text-wcnteal-400 bg-wcnteal-500/15 px-2 py-0.5 rounded\">利润率 34.0%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 调整后 EBITDA 达 $8.958 亿美元，同比提升 7.9%，底层利润率扩张 50 个基点。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>营运现金流 (Q3 单季)</span>\n <span class=\"p-1.5 rounded-lg bg-wcnblue-500/15 text-wcnblue-600 dark:text-wcnblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$691.9M</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">现金创收强劲</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 第三季度经营活动现金流达 $6.919 亿美元，展现出卓越的高质量现金流转化能力。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 商业模式与固废独占网络架构 (Business Model & Exclusive Network Architecture)\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-wcnblue-600 dark:text-wcnblue-400\">Section 01 · Business Model & Exclusive Network Architecture</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 商业模式与固废独占网络架构：次级市场深耕、垂直整合与M&A扩张</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY26E 总营收 ~$10.09B · 专注于北美次级及独占市场</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2022–2026E 全球总营收与调整后 EBITDA 演进趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">通过次级市场深耕与高质量并购，总营收稳步突破 100 亿美元大关，EBITDA 利润率保持稳步扩张</p>\n </div>\n <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n <button onclick=\"switchBizChart('revenue_mix')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-wcnblue-600 dark:text-wcnblue-300 shadow-sm transition cursor-pointer\">视图A：总营收与 EBITDA 演进</button>\n <button onclick=\"switchBizChart('segment_metrics')\" id=\"btn-chart-seg\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer\">视图B：Q3 各子板块营收增速</button>\n </div>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizArchitectureChart\"></canvas>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">Waste Connections 三大核心战略优势</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-wcnblue-500/15 text-wcnblue-600 dark:text-wcnblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">聚焦北美次级与独占市场（Secondary & Exclusive Markets）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 避开高度饱和的一线大都会红海竞争，WCN 深度布局美国西部、南部及加拿大等次级与排他性市场，在当地拥有极高的市场份额和天然的定价保护伞。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">高质量、高回报的并购整合（M&A Flywheel）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 持续在全美收购中小型优质固废及 E&P 废物处理家族企业，通过统一管理与运力整合快速实现利润率向集团平均水准靠拢。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-wcnteal-500/15 text-wcnteal-600 dark:text-wcnteal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">多元化垂直板块（固废 + 回收 + E&P 废弃物）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 业务涵盖固废收集、填埋、回收物销售以及受益于钻探回暖的油气田（E&P）废物处理，构筑了多元且互补的现金流创收矩阵。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">全年业绩预期上调</span>\n <span class=\"font-bold text-wcnblue-600 dark:text-wcnblue-400\">FY26 营收预期上调至 $10.09B · 自由现金流 $1.4B+</span>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-wcnblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-wcnblue-500/15 text-wcnblue-700 dark:text-wcnblue-300 text-xs font-bold\">基本盘基石 · 占总营收 ~70%+</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">Solid Waste Collection & Disposal</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. 固体废弃物收集与处置板块</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n Q3 固体废弃物收集营收增长 5.5% 至 $18.2 亿美元，处置与转运营收增长 7.8% 至 $4.92 亿美元。核心价格大增 5.5%（收益率 4.3%），填埋场垃圾吨数增长 3%（其中特殊废弃物增长 7%，建筑及拆除废物 C&D 增长 5%）。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>核心价格涨幅 +5.5% / 收益率 4.3%</span>\n <span class=\"text-wcnblue-600 dark:text-wcnblue-400 font-semibold\">填埋场特殊废弃物大增 7%</span>\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-emerald-500/15 text-emerald-700 dark:text-emerald-400 text-xs font-bold\">高增长辅助引擎 · 回收与E&P废物</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">Recycling & E&P Waste</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">2. 回收循环与 E&P 废物处理板块</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n Q3 固废回收营收强劲增长 15.1% 至 $6,470 万美元（受益于废纸瓦楞纸 OCC 价格回暖及 RNG 销售大增 35%）；同时受益于美国钻探活跃度回升，E&P 废物处理营收攀升 18.8% 至 $2.129 亿美元。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>回收营收 +15.1% / E&P 营收 +18.8%</span>\n <span class=\"text-emerald-600 dark:text-emerald-400 font-semibold\">填埋气及 RNG 销售同比大增 35%</span>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 行业地位与核心护城河 (Industry Position & Moat)\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · Industry Position & Economic Moat</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四大核心护城河：次级市场排他性、卓越安全运营与M&A整合力</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Moat · 北美次级固废独占垄断)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-wcnblue-500/15 text-wcnblue-600 dark:text-wcnblue-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">次级与独占市场的排他性竞争壁垒</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 在次级市场中，竞争对手极难复制其纵向一体化的“收集-转运-填埋”完整闭环，赋予了 WCN 远超行业平均的定价自由度。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">行业领先的员工留存率与创纪录安全表现</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 秉持“以人为本”的 decentralized 运营文化，WCN 在车队安全管理和员工留存率上连续多年位居北美固废行业第一梯队。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-wcnteal-500/15 text-wcnteal-600 dark:text-wcnteal-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">成熟且高效的家族企业并购整合能力</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 拥有数十年来久经考验的 M&A 整合中枢，能够以极低摩擦将新收购的区域独立垃圾处理公司纳入标准化系统，释放协同利润。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">抗通胀定价机制与极佳的现金转化率</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 刚需服务属性加上长期合同中内置的 CPI 及燃料附加条款，使其在通胀期能够顺畅传导成本压力并转化为高额现金流。\n </p>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">北美固废处理巨头五维护城河雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">Waste Connections (WCN) vs 废物管理 (WM) vs 共和服务 (RSG)（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三、 北美固废与环保巨头横向对比 (Competitive Landscape)\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-wcnblue-600 dark:text-wcnblue-400\">Section 03 · North American Waste Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 北美固废与环保巨头横向对比：次级市场聚焦 vs 一线城市全国网格</h2>\n </div>\n <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-wcnblue-500 text-white shadow-sm transition cursor-pointer\">全部巨头</button>\n <button onclick=\"filterCompetitors('waste')\" data-filter=\"waste\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">北美固废处理三巨头</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">企业名称与核心定位</th>\n <th class=\"py-4 px-4 min-w-[130px]\">核心主营业务</th>\n <th class=\"py-4 px-4 min-w-[140px]\">最新营收规模 (Q3)</th>\n <th class=\"py-4 px-4 min-w-[100px]\">定价权与核心价格</th>\n <th class=\"py-4 px-4 min-w-[115px]\">调整后 EBITDA 利润率</th>\n <th class=\"py-4 px-5 min-w-[230px]\">核心优劣势与竞合定位评估</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n <tr data-category=\"waste\" class=\"bg-wcnblue-500/5 dark:bg-wcnblue-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-wcnblue-600 text-white text-[10px] font-extrabold\">次级市场王者</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">威斯特连接 (WCN)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Waste Connections, Inc.</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">次级固废 + 填埋处置 + E&P 废物</td>\n <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">$26.4 亿 (Q3)</td>\n <td class=\"py-4 px-4 font-mono font-bold text-wcnblue-600 dark:text-wcnblue-300\">核心价格 +5.5%</td>\n <td class=\"py-4 px-4 font-mono font-bold text-emerald-600 dark:text-emerald-400\">34.0% (+20 bps)</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>专注次级独占市场：</strong>通过独特的区域垄断与 M&A 飞轮驱动，Q3 盈利超预期并再次上调全年指引，成长性极佳。\n </td>\n </tr>\n\n <tr data-category=\"waste\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">废物管理公司 (WM)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Waste Management, Inc.</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">全美固废收集 + 填埋 + RNG + 医疗</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">~$6.85 亿/季</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">核心价格 +5.8%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~29%–30%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>全美体量最大龙头：</strong>网格化覆盖一线大都会，拥有庞大填埋场资产与 RNG 新能源布局。\n </td>\n </tr>\n\n <tr data-category=\"waste\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">共和服务 (RSG)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Republic Services, Inc.</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">有害/无害废弃物处理 + 可持续发展</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">~$4B+/季</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">强劲定价纪律</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~30%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>北美固废双雄之一：</strong>在车队电气化与可持续环保项目上表现亮眼，与 WM、WCN 形成坚不可摧的三巨头格局。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">北美固废三巨头 EBITDA 利润率与核心价格涨幅对照</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">Waste Connections 调整后 EBITDA 利润率达 34.0%，在次级市场展现出卓越的盈利空间</p>\n </div>\n <span class=\"text-xs font-semibold text-wcnblue-700 dark:text-wcnblue-300 bg-wcnblue-500/15 px-2.5 py-1 rounded\">34.0% EBITDA 利润率行业领先</span>\n </div>\n <div class=\"relative h-64 w-full\">\n <canvas id=\"compMarginChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 财务健康与自由现金流推演 (Financial Health & Compounding Simulator)\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 04 · Financial Health & Free Cash Flow Simulator</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与自由现金流体系：$6.92亿 Q3 营运现金流与 $1.4B+ FCF 指引</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">Q3 营运现金流 $691.9M · 全年调整后 FCF $1.4–$1.45B</span>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-wcnblue-600 dark:text-wcnblue-400 uppercase\">Adjusted EBITDA Margin</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">34.0%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n Q3 调整后 EBITDA 利润率扩大 20 个基点至 34.0%（底层利润率扩张 50 bps），价格成本剪刀差持续释放。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Operating Cash Flow (Q3)</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$691.9M</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 单季经营活动现金流达 $6.919 亿美元（去年同期 $6.774 亿），现金造血能力极为卓越。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-wcnteal-600 dark:text-wcnteal-400 uppercase\">Adjusted FCF Outlook</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$1.4–$1.45B</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 全年调整后自由现金流预计维持在 $14.0 亿至 $14.5 亿美元的高位，支撑持续的回购与派息。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">Share Repurchases (9M)</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$944.4M</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 前三季度共计花费 9.444 亿美元用于普通股回购，另有 2.655 亿美元用于现金分红。\n </p>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2021–2026E 全球总营收与调整后 EBITDA 演进趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">内生增长与并购协同驱动营收与 EBITDA 呈现强劲的复合复利增长曲线</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-wcnblue-700 dark:text-wcnblue-300 bg-wcnblue-500/15 px-2.5 py-1 rounded\">卓越的固废复合增长曲线</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"valEvolutionChart\"></canvas>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 rounded-2xl p-6 sm:p-8 text-white border border-slate-700 shadow-xl space-y-6 no-print\">\n <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-3 pb-4 border-b border-slate-700/80\">\n <div>\n <div class=\"inline-flex items-center space-x-2 text-xs font-mono uppercase tracking-wider text-wcnblue-300 font-bold\">\n <span>WCN COMPOUNDING SIMULATOR · 威斯特连接长期复利与自由现金流推演器</span>\n </div>\n <h3 class=\"text-lg sm:text-xl font-bold text-white mt-1\">Waste Connections 长期持仓复利与股息再投资动态推演器</h3>\n <p class=\"text-xs text-slate-400 mt-0.5\">基准参数：当前参考股价 ~$196.14 | 调整后 FCF ~$1.42B | 模拟多年期自由现金流与股东回报复利模型</p>\n </div>\n <label class=\"inline-flex items-center space-x-2.5 px-3.5 py-2 rounded-xl bg-wcnblue-500/15 border border-wcnblue-400/30 text-xs font-semibold text-wcnblue-300 cursor-pointer shrink-0\">\n <input type=\"checkbox\" id=\"drip-toggle\" checked onchange=\"updateDividendSimulator()\" class=\"w-4 h-4 rounded accent-[#2563EB] cursor-pointer\">\n <span>开启股息与回购自动再投资 (DRIP)</span>\n </label>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-5 space-y-4 text-xs\">\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">初始模拟投资额 (USD)</span>\n <span id=\"sim-principal-label\" class=\"font-mono font-bold text-white text-sm\">$30,000</span>\n </div>\n <input id=\"sim-principal\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"30000\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#2563EB] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">长期持有年限 (Years)</span>\n <span id=\"sim-years-label\" class=\"font-mono font-bold text-white text-sm\">5 年</span>\n </div>\n <input id=\"sim-years\" type=\"range\" min=\"1\" max=\"10\" step=\"1\" value=\"5\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#2563EB] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">年均自由现金流与净利润复合增长率</span>\n <span id=\"sim-growth-label\" class=\"font-mono font-bold text-emerald-400 text-sm\">9.0%</span>\n </div>\n <input id=\"sim-growth\" type=\"range\" min=\"4\" max=\"16\" step=\"0.5\" value=\"9.0\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#10B981] cursor-pointer\">\n </div>\n\n <div class=\"pt-1\">\n <div class=\"text-slate-300 font-medium mb-2\">远期市盈率估值倍数预期（Forward P/E Multiple）：</div>\n <div class=\"grid grid-cols-3 gap-2\" id=\"tax-btn-group\">\n <button type=\"button\" onclick=\"setTaxRate(35)\" data-tax=\"35\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-wcnblue-400 transition cursor-pointer\">\n 35x 保守估值<br><span class=\"text-[10px] text-slate-400\">历史公用事业区间</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(42)\" data-tax=\"42\" class=\"tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-wcnblue-500 text-white border border-wcnblue-400 shadow transition cursor-pointer\">\n 42x 合理中枢<br><span class=\"text-[10px] text-slate-200\">固废龙头均值</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(48)\" data-tax=\"48\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-wcnblue-400 transition cursor-pointer\">\n 48x 牛市溢价<br><span class=\"text-[10px] text-slate-400\">次级市场溢价</span>\n </button>\n </div>\n </div>\n </div>\n\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末预计投资资产估值 (USD)</div>\n <div id=\"sim-final-value\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-white mt-1.5\">$54,620</div>\n <div id=\"sim-total-return\" class=\"text-xs font-semibold text-emerald-400 mt-1.5\">累计总回报 +82.1% (基于 42x P/E)</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末隐含年化每股收益 (EPS)</div>\n <div id=\"sim-annual-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-wcnblue-300 mt-1.5\">$6.85</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">伴随并购协同与定价权持续复利增长</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末对应估值多维年化回报率 (CAGR)</div>\n <div id=\"sim-yoc\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-teal-400 mt-1.5\">12.7%</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">年化复合投资回报增长</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末股息回报率预估 (Dividend Yield)</div>\n <div id=\"sim-cum-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-emerald-400 mt-1.5\">~0.8%</div>\n <div class=\"text-shares-end text-xs text-slate-400 mt-1.5\">以股票回购与派息并重的回报</div>\n </div>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">次级市场定价权 + 高回报并购飞轮</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>卓越的次级市场定价权（核心价格 +5.5%）：</strong>在排他性市场中享有极高的议价能力，完美对冲通胀。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>Q3 盈利大超预期并上调指引：</strong>营收达 $2.64B（+7.3% YoY），调整后 EBITDA 利润率达 34.0%，再次上调全年展望。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>高效的并购整合与回购：</strong>M&A 持续贡献增量，前三季度完成 $9.44B（注：原为 $944.4M）股票回购，股东回报坚实。</span></li>\n </ul>\n </div>\n\n <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">高估值多重倍数 + 柴油成本波动</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>估值处于历史相对高位：</strong>Forward P/E 达到 ~44x 附近，市场对优质固废公用事业的成长和防御定价充分。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>柴油价格飙升带来的利润率逆风：</strong>季度末柴油价格飙升对调整后 EBITDA 利润率造成约 30 个基点的阶段性压制。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span>住宅建设周期受高利率压制：受高利率环境影响，民用住宅建设及相关新房建造垃圾清运增速相对承压。</span></li>\n </ul>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 投资决策与风险配置框架 (Investment Decision & Risk)\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-wcnblue-600 dark:text-wcnblue-400\">Section 05 · Investment Decision & Risk Allocation</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景目标价推演与固废组合策略</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：高品质公用事业成长底仓 · 逢回调积极布局</span>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">概率：25%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">48x–52x P/E ($225–$245)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>次级市场定价权进一步放大，M&A 并购规模超预期；RNG 能源与碳信用价值大增，市场给予其稀缺公用事业成長溢价。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n 潜在年化总回报：+18% 至 +25%\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-wcnblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-wcnblue-500/15 text-wcnblue-700 dark:text-wcnblue-300 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-wcnblue-600 dark:text-wcnblue-400\">概率：55%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">40x–44x P/E ($190–$210)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>2026–2028 稳步兑现中高个位数营收增长与双位数自由现金流增长，估值维持在 42x 附近历史合理中枢。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-wcnblue-600 dark:text-wcnblue-400\">\n 稳健年化总回报：+11% 至 +14%（定价权与回购红利）\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">32x–35x P/E ($150–$165)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>宏观经济严重放缓导致固废总体积下滑，柴油等运营成本持续高位施压利润率，估值倍数受到宏观收紧压制。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 潜在回撤风险：-15% 至 -22%（强劲现金流与独占垄断底线支撑）\n </div>\n </div>\n </div>\n\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心潜在风险与跟踪边界</h3>\n <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 柴油与燃油成本飙升</span>\n <span class=\"text-xs font-mono text-rose-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">车队燃油成本对利润率的阶段性冲击</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 尽管有燃油附加费对冲，但季度末突发的柴油价格飙升仍对调整后 EBITDA 利润率造成了约 30 个基点的短期逆风。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 次级市场 M&A 并购标的稀缺性</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">优质并购标的估值与获取难度</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 随着全美固废行业整合度不断提高，优质次级市场家族企业的收购价格可能水涨船高，考验资本配置效率。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-wcnblue-500/10 text-wcnblue-600 dark:text-wcnblue-400 text-xs font-bold\">03 · E&P 油气田废物处理周期波动</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">美国上游钻探活跃度与原油价格联动</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n E&P 废物处理板块（Q3 增长 18.8%）高度依赖油气钻探活跃度，若能源价格剧烈震荡将对该细分板块产生扰动。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">04 · 宏观经济与民用住宅建设放缓</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">高利率对住宅建设及 C&D 废弃物的影响</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 高利率持续压制住宅地产建设，对民用收运及部分建筑垃圾产生温和压力。\n </p>\n </div>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-wcnblue-300 mb-4 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构级投资组合配置纪律与固废成长策略</span>\n </h3>\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-white mb-1\">1. 高品质固废成长核心底仓</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 将 WCN 定位为兼具公用事业防通胀定价权与次级市场高成长弹性的核心底仓标的，提供长线超额收益。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-wcnblue-300 mb-1\">2. 股价回调左侧建仓锚点</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 鉴于成长股估值常年处于较高水平，若短期因燃油成本或市场震荡回调至 <strong>$180–$188 区间</strong>，建议分批增持。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-emerald-400 mb-1\">3. 资产配置税务与长线持有</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 优先在长线账户中配置，充分享受 Waste Connections 凭借次级市场垄断与 M&A 飞轮带来的长期复利回报。\n </p>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-wcnblue-500/15 text-wcnblue-700 dark:text-wcnblue-300 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选季度财报中已验证达标的经营指标（勾选状态自动本地保存），持续校验 Waste Connections 定价权、利润率与自由现金流：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#2563EB]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 核心价格涨幅（Core price 目标 5%–6%）与定价纪律</span>\n <span class=\"text-[11px] font-mono text-wcnblue-600 dark:text-wcnblue-400 font-semibold shrink-0\">定价权核心锚</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 检查每季财报核心价格是否稳健上涨（如 Q3 达 5.5% YoY），验证次级市场定价保护伞。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#2563EB]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 调整后 EBITDA 利润率维持在 34% 高位并实现底层扩张</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">盈利质量指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪每季度调整后 EBITDA 利润率（如 Q3 达 34.0%，底层扩张 50 bps），评估成本控制成效。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#2563EB]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 全年调整后自由现金流达成 $14.0B–$14.5B 指引</span>\n <span class=\"text-[11px] font-mono text-wcnteal-600 dark:text-wcnteal-400 font-semibold shrink-0\">现金造血能力</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 检验全年 FCF 预期及单季经营现金流（如 Q3 达 $691.9M）是否稳定兑现。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#2563EB]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. M&A 并购扩张持续贡献增量营收（目标符合历史常规）</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">外延成长动能</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控每季度收购带来的营收贡献（如 Q3 贡献净收购营收 $5,300 万美元）及整合回报。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#2563EB]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 填埋场特殊废弃物与 C&D 垃圾处理量复苏表现</span>\n <span class=\"text-[11px] font-mono text-wcnblue-600 dark:text-wcnblue-400 font-semibold shrink-0\">填埋业务景气度</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 评估填埋场特殊废弃物（如 Q3 增长 7%）及 C&D 废弃物吨数的季度变化趋势。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#2563EB]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 股东资本回报执行（股份回购与现金分红派发节奏）</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">股东现金回报</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监督前三季度 $9.444 亿回购与 $2.655 亿分红的持续落地，确认股东回报承诺。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>威斯特连接公司 Waste Connections, Inc. (NYSE: WCN) 深度商业与投资价值分析报告 · 机构研究框架版 [cite: 1.1.2]</span>\n <span>数据基准：2026Q3 财报 (SEC Form 10-Q) 及 2026 年 11 月市场一致预期 (FY26E) [cite: 1.1.3, 1.2.4]</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本深度研究报告基于 Waste Connections 公开财务报告（10-Q/10-K）、2026Q3 财报业绩公告及北美固废环保行业调研资料整理生成，旨在提供结构化的产业分析与龙头估值框架。报告中涉及的盈利预测、自由现金流指引、三情景目标价及复利模拟均基于特定假设条件推演，不构成任何证券买卖建议、税务规划意见或收益承诺。\n </p>\n </footer>\n\n </div>\n </main>\n\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-wcnblue-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-wcnblue-400');\n }\n }\n });\n });\n\n function filterCompetitors(category) {\n document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n if (btn.dataset.filter === category) {\n btn.classList.add('bg-wcnblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n } else {\n btn.classList.remove('bg-wcnblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n }\n });\n\n const rows = document.querySelectorAll('#comp-table-body tr');\n rows.forEach(row => {\n const rowCat = row.dataset.category;\n if (category === 'all' || rowCat === 'waste' || rowCat === category) {\n row.style.display = '';\n } else {\n row.style.display = 'none';\n }\n });\n }\n\n let currentMultiple = 42;\n\n function setTaxRate(mult) {\n currentMultiple = mult;\n document.querySelectorAll('#tax-btn-group .tax-btn').forEach(btn => {\n const btnMult = parseFloat(btn.dataset.tax);\n if (Math.abs(btnMult - mult) < 0.001) {\n btn.className = 'tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-wcnblue-500 text-white border border-wcnblue-400 shadow transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-slate-200';\n } else {\n btn.className = 'tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-wcnblue-400 transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-slate-400';\n }\n });\n updateDividendSimulator();\n }\n\n function updateDividendSimulator() {\n const principal = parseFloat(document.getElementById('sim-principal').value);\n const years = parseInt(document.getElementById('sim-years').value, 10);\n const growthPct = parseFloat(document.getElementById('sim-growth').value);\n\n document.getElementById('sim-principal-label').textContent = '$' + principal.toLocaleString('en-US');\n document.getElementById('sim-years-label').textContent = years + ' 年';\n document.getElementById('sim-growth-label').textContent = growthPct.toFixed(1) + '%';\n\n const initEps = 4.46; // FY26E EPS approx proxy\n const g = growthPct / 100;\n\n let finalEps = initEps * Math.pow(1 + g, years);\n let estimatedStockPrice = finalEps * currentMultiple;\n let initialStockPrice = 196.14;\n let totalReturnPct = ((estimatedStockPrice - initialStockPrice) / initialStockPrice) * 100;\n let finalPortfolioVal = principal * (1 + totalReturnPct / 100);\n let cagr = (Math.pow(finalPortfolioVal / principal, 1 / years) - 1) * 100;\n\n document.getElementById('sim-final-value').textContent = '$' + Math.round(finalPortfolioVal).toLocaleString('en-US');\n document.getElementById('sim-total-return').textContent = `累计总回报 +${totalReturnPct.toFixed(1)}% (基于 ${currentMultiple}x P/E)`;\n document.getElementById('sim-annual-div').textContent = '$' + finalEps.toFixed(2);\n document.getElementById('sim-yoc').textContent = cagr.toFixed(1) + '%';\n document.getElementById('sim-cum-div').textContent = `~0.8%`;\n }\n\n const KPI_STORAGE_KEY = 'wcn_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizChartInstance = null;\n let radarChartInstance = null;\n let compMarginChartInstance = null;\n let valEvolutionChartInstance = null;\n let currentBizMode = 'revenue_mix';\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizChart() {\n const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n const colors = getChartColors();\n\n const revConfig = {\n type: 'bar',\n data: {\n labels: ['2022', '2023', '2024', '2025', '2026E'],\n datasets: [\n {\n label: '全年总营收 ($B)',\n data: [7.3, 8.0, 8.8, 9.4, 10.09],\n backgroundColor: '#2563EB',\n borderRadius: 4,\n stack: 'rev'\n },\n {\n type: 'line',\n label: '调整后 EBITDA 利润率 (%)',\n data: [33.2, 33.5, 33.8, 33.9, 34.0],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 2.5,\n pointRadius: 4,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => ctx.dataset.yAxisID === 'y1' ? `EBITDA 利润率: ${ctx.parsed.y}%` : `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}B`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n min: 0,\n max: 12,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 20,\n max: 40,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11 }, callback: v => v + '%' }\n }\n }\n }\n };\n\n const segConfig = {\n type: 'bar',\n data: {\n labels: [\n 'Q3 固废收集营收增速 (%)',\n 'Q3 固废处置与转运增速 (%)',\n 'Q3 固废回收业务增速 (%)',\n 'Q3 E&P 废物处理增速 (%)'\n ],\n datasets: [\n {\n label: 'Q3 2026 各子板块营收增速',\n data: [5.5, 7.8, 15.1, 18.8],\n backgroundColor: [\n '#2563EB',\n '#06B6D4',\n '#10B981',\n '#F97316'\n ],\n borderRadius: 6,\n barThickness: 26\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `同比增速: +${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n min: 0,\n max: 25,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 } }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n };\n\n if (bizChartInstance) bizChartInstance.destroy();\n bizChartInstance = new Chart(ctx, currentBizMode === 'revenue_mix' ? revConfig : segConfig);\n }\n\n function switchBizChart(mode) {\n currentBizMode = mode;\n const btnRev = document.getElementById('btn-chart-rev');\n const btnSeg = document.getElementById('btn-chart-seg');\n const titleEl = document.getElementById('biz-chart-title');\n const subEl = document.getElementById('biz-chart-sub');\n\n if (mode === 'revenue_mix') {\n btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-wcnblue-600 dark:text-wcnblue-300 shadow-sm transition cursor-pointer';\n btnSeg.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2022–2026E 全球总营收与调整后 EBITDA 演进趋势';\n subEl.textContent = '通过次级市场深耕与高质量并购，总营收稳步突破 100 亿美元大关，EBITDA 利润率保持稳步扩张';\n } else {\n btnSeg.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-wcnblue-600 dark:text-wcnblue-300 shadow-sm transition cursor-pointer';\n btnRev.className = 'px-2.5 py-1 rounded-medium font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2026Q3 各子板块营收同比增速拆解';\n subEl.textContent = '固废收集增长 5.5%，处置转运增长 7.8%，回收大增 15.1%，E&P 废物处理大增 18.8%';\n }\n initBizChart();\n }\n\n function initRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (radarChartInstance) radarChartInstance.destroy();\n radarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '次级与独占市场定价权',\n '家族企业并购整合飞轮',\n '员工留存与安全运营记录',\n '抗通胀核心价格保护伞',\n '多元化现金流与 E&P 协同'\n ],\n datasets: [\n {\n label: 'Waste Connections (WCN)',\n data: [9.8, 9.9, 9.6, 9.8, 9.4],\n borderColor: '#2563EB',\n backgroundColor: 'rgba(37, 99, 235, 0.24)',\n pointBackgroundColor: '#2563EB',\n borderWidth: 2.5\n },\n {\n label: '废物管理公司 (WM)',\n data: [9.7, 9.2, 9.0, 9.8, 9.2],\n borderColor: '#10B981',\n backgroundColor: 'rgba(16, 185, 129, 0.14)',\n pointBackgroundColor: '#10B981',\n borderWidth: 2.0\n },\n {\n label: '共和服务 (RSG)',\n data: [9.5, 9.0, 9.2, 9.6, 8.8],\n borderColor: '#06B6D4',\n backgroundColor: 'rgba(6, 182, 212, 0.12)',\n pointBackgroundColor: '#06B6D4',\n borderWidth: 1.8,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initCompMarginChart() {\n const ctx = document.getElementById('compMarginChart').getContext('2d');\n const colors = getChartColors();\n\n if (compMarginChartInstance) compMarginChartInstance.destroy();\n compMarginChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: [\n '威斯特连接 (WCN · 次级固废王者)',\n '废物管理公司 (WM · 北美固废霸主)',\n '共和服务 (RSG · 环保双雄之一)'\n ],\n datasets: [\n {\n label: '调整后 EBITDA 利润率 (%)',\n data: [34.0, 29.5, 30.0],\n backgroundColor: '#2563EB',\n borderRadius: 5,\n barThickness: 18\n },\n {\n label: '核心价格涨幅 Core Price (%)',\n data: [5.5, 5.8, 5.5],\n backgroundColor: '#10B981',\n borderRadius: 5,\n barThickness: 18\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n max: 40,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initValEvolutionChart() {\n const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n const colors = getChartColors();\n\n if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n valEvolutionChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2021', '2022', '2023', '2024', '2025', '2026E'],\n datasets: [\n {\n type: 'bar',\n label: '全年总营收 ($ 亿美元)',\n data: [6.7, 7.3, 8.0, 8.8, 9.4, 10.09],\n backgroundColor: 'rgba(37, 99, 235, 0.85)',\n borderRadius: 5,\n barThickness: 28,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '调整后自由现金流 ($ 亿美元)',\n data: [1.1, 1.2, 1.3, 1.4, 1.42, 1.45],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 3,\n pointRadius: 5,\n pointHoverRadius: 7,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}B`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 0,\n max: 12,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v.toFixed(1) + 'B' },\n title: { display: true, text: '总营收 ($B)', color: colors.text, font: { size: 11 } }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 0,\n max: 2.0,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v.toFixed(1) + 'B' },\n title: { display: true, text: '调整后 FCF ($B)', color: '#10B981', font: { size: 11 } }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n updateDividendSimulator();\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n });\n </script>\n</body>\n</html>\n"};
